import{_ as e,c as a,o as t,a0 as r}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"fr/blog/pre-shot-routines.md","filePath":"fr/blog/pre-shot-routines.md"}');const n=e({name:"fr/blog/pre-shot-routines.md"},[["render",function(e,i,n,o,s,l){return t(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="elaboration-de-routines-d-39-avant-tournage" tabindex="-1">Élaboration de routines d&#39;avant-tournage <a class="header-anchor" href="#elaboration-de-routines-d-39-avant-tournage" aria-label="Permalink to &quot;Élaboration de routines d&amp;#39;avant-tournage&quot;">​</a></h1><p>La différence entre un bon lancer et un lancer exceptionnel se joue souvent avant même que la boule ne quitte votre main. Une routine d&#39;avant-lancer bien conçue est votre point d&#39;ancrage dans la tempête de la compétition : une séquence fiable qui prépare votre esprit et votre corps à une performance optimale.</p><h2 id="pourquoi-les-routines-d-39-avant-tir-sont-importantes" tabindex="-1">Pourquoi les routines d&#39;avant-tir sont importantes <a class="header-anchor" href="#pourquoi-les-routines-d-39-avant-tir-sont-importantes" aria-label="Permalink to &quot;Pourquoi les routines d&amp;#39;avant-tir sont importantes&quot;">​</a></h2><p>Les athlètes de haut niveau, tous sports confondus, utilisent des rituels d&#39;avant-coup. À la pétanque, où chaque lancer est précis et où la pression peut monter entre les coups, ces rituels remplissent plusieurs fonctions :</p><ul><li><strong>Cohérence</strong> : Une même préparation conduit à une exécution plus cohérente</li><li><strong>Concentration</strong> : Donne à votre esprit une tâche constructive au lieu de s’inquiéter.</li><li><strong>Transition</strong> : Vous aide à passer de la réflexion à l’action</li><li><strong>Gestion du stress</strong> : Les actions familières calment le système nerveux</li><li><strong>Réinitialiser</strong> : Efface le tir précédent de votre mémoire</li></ul><h2 id="anatomie-d-39-une-routine-efficace" tabindex="-1">Anatomie d&#39;une routine efficace <a class="header-anchor" href="#anatomie-d-39-une-routine-efficace" aria-label="Permalink to &quot;Anatomie d&amp;#39;une routine efficace&quot;">​</a></h2><p>Une bonne routine avant le tir comporte trois phases :</p><h3 id="phase-1-evaluation-5-10-secondes" tabindex="-1">Phase 1 : Évaluation (5-10 secondes) <a class="header-anchor" href="#phase-1-evaluation-5-10-secondes" aria-label="Permalink to &quot;Phase 1 : Évaluation (5-10 secondes)&quot;">​</a></h3><ul><li>Analysez le terrain.</li><li>Visualisez le résultat souhaité</li><li>Choisissez votre type de jet</li><li>Engagez-vous à respecter la décision</li></ul><h3 id="phase-2-preparation-5-10-secondes" tabindex="-1">Phase 2 : Préparation (5-10 secondes) <a class="header-anchor" href="#phase-2-preparation-5-10-secondes" aria-label="Permalink to &quot;Phase 2 : Préparation (5-10 secondes)&quot;">​</a></h3><ul><li>Prenez votre place</li><li>Trouvez votre prise</li><li>Calmez votre respiration</li><li>Sentez le poids de la boule</li></ul><h3 id="phase-3-execution-3-5-secondes" tabindex="-1">Phase 3 : Exécution (3-5 secondes) <a class="header-anchor" href="#phase-3-execution-3-5-secondes" aria-label="Permalink to &quot;Phase 3 : Exécution (3-5 secondes)&quot;">​</a></h3><ul><li>Concentration finale sur la cible</li><li>Faites confiance à votre corps</li><li>Libérer sans réfléchir</li><li>Suivre naturellement</li></ul><h2 id="elaborer-sa-routine-personnelle" tabindex="-1">Élaborer sa routine personnelle <a class="header-anchor" href="#elaborer-sa-routine-personnelle" aria-label="Permalink to &quot;Élaborer sa routine personnelle&quot;">​</a></h2><h3 id="etape-1-observez-vos-habitudes-actuelles" tabindex="-1">Étape 1 : Observez vos habitudes actuelles <a class="header-anchor" href="#etape-1-observez-vos-habitudes-actuelles" aria-label="Permalink to &quot;Étape 1 : Observez vos habitudes actuelles&quot;">​</a></h3><p>Avant de créer une nouvelle routine, observez ce que vous faites déjà :</p><ul><li>Que faites-vous avant de réussir vos lancers ?</li><li>Qu&#39;est-ce qui change lorsque vous êtes sous pression ?</li><li>Qu&#39;est-ce qui vous semble naturel ?</li></ul><h3 id="etape-2-concevez-votre-sequence" tabindex="-1">Étape 2 : Concevez votre séquence <a class="header-anchor" href="#etape-2-concevez-votre-sequence" aria-label="Permalink to &quot;Étape 2 : Concevez votre séquence&quot;">​</a></h3><p>Créez une routine qui comprend :</p><p><strong>Éléments physiques :</strong></p><ul><li>Comment abordez-vous le cercle ?</li><li>Comment prendre et tenir la boule</li><li>Votre posture et votre positionnement</li><li>Un schéma respiratoire spécifique</li></ul><p><strong>Éléments mentaux :</strong></p><ul><li>Visualisation du résultat</li><li>Un mot ou une expression clé</li><li>Un point d&#39;engagement (le moment où vous décidez « c&#39;est le lancer »)</li></ul><h3 id="etape-3-faites-simple" tabindex="-1">Étape 3 : Faites simple <a class="header-anchor" href="#etape-3-faites-simple" aria-label="Permalink to &quot;Étape 3 : Faites simple&quot;">​</a></h3><p>Votre routine devrait être :</p><ul><li><strong>Assez court</strong> pour être maintenu sous pression (15 à 25 secondes au total)</li><li><strong>Assez simple</strong> pour s&#39;en souvenir en cas de stress</li><li><strong>Suffisamment flexible</strong> pour s&#39;adapter à différentes situations</li></ul><h2 id="exemples-de-routines" tabindex="-1">Exemples de routines <a class="header-anchor" href="#exemples-de-routines" aria-label="Permalink to &quot;Exemples de routines&quot;">​</a></h2><h3 id="la-routine-du-pointeur" tabindex="-1">La routine du pointeur <a class="header-anchor" href="#la-routine-du-pointeur" aria-label="Permalink to &quot;La routine du pointeur&quot;">​</a></h3><ol><li>Placez-vous derrière le cercle, évaluez le terrain.</li><li>Visualisez la trajectoire de la boule et son point d&#39;atterrissage.</li><li>Entrez dans le cercle, trouvez votre position</li><li>Trois respirations lentes en sentant la boule</li><li>Gardez les yeux sur la cible, lâchez</li></ol><h3 id="la-routine-du-tireur" tabindex="-1">La routine du tireur <a class="header-anchor" href="#la-routine-du-tireur" aria-label="Permalink to &quot;La routine du tireur&quot;">​</a></h3><ol><li>Identifiez la boule cible, choisissez l&#39;angle</li><li>Visualisez l&#39;impact et le résultat</li><li>Entrez dans le cercle avec un but précis.</li><li>Une profonde inspiration, sentir le poids</li><li>Fixez la cible du regard, exécutez.</li></ol><h2 id="erreurs-courantes-a-eviter" tabindex="-1">Erreurs courantes à éviter <a class="header-anchor" href="#erreurs-courantes-a-eviter" aria-label="Permalink to &quot;Erreurs courantes à éviter&quot;">​</a></h2><h3 id="trop-long" tabindex="-1">Trop long <a class="header-anchor" href="#trop-long" aria-label="Permalink to &quot;Trop long&quot;">​</a></h3><p>Si votre routine dure plus de 30 secondes, vous réfléchissez trop. Les routines longues laissent plus de temps à l&#39;anxiété pour s&#39;installer.</p><h3 id="trop-rigide" tabindex="-1">Trop rigide <a class="header-anchor" href="#trop-rigide" aria-label="Permalink to &quot;Trop rigide&quot;">​</a></h3><p>Si la moindre interruption perturbe votre routine, celle-ci est trop fragile. Intégrez de la flexibilité : si quelque chose interrompt votre concentration, prévoyez une procédure de réinitialisation.</p><h3 id="sauter-a-la-corde-sous-pression" tabindex="-1">Sauter à la corde sous pression <a class="header-anchor" href="#sauter-a-la-corde-sous-pression" aria-label="Permalink to &quot;Sauter à la corde sous pression&quot;">​</a></h3><p>La routine est d&#39;autant plus importante que la pression est forte. L&#39;abandonner en période de stress vous prive de ses bienfaits protecteurs.</p><h3 id="se-concentrer-sur-la-mecanique" tabindex="-1">Se concentrer sur la mécanique <a class="header-anchor" href="#se-concentrer-sur-la-mecanique" aria-label="Permalink to &quot;Se concentrer sur la mécanique&quot;">​</a></h3><p>Votre routine devrait se terminer par une concentration sur le résultat, et non sur la technique. « Atteignez la cible », pas « gardez le coude droit ».</p><h2 id="pratiquer-votre-routine" tabindex="-1">Pratiquer votre routine <a class="header-anchor" href="#pratiquer-votre-routine" aria-label="Permalink to &quot;Pratiquer votre routine&quot;">​</a></h2><h3 id="en-formation" tabindex="-1">En formation <a class="header-anchor" href="#en-formation" aria-label="Permalink to &quot;En formation&quot;">​</a></h3><ul><li>Utilisez votre routine complète pour chaque lancer, même les plus informels.</li><li>Chronométrez-vous pour garantir la régularité</li><li>S&#39;entraîner avec des distractions pour développer sa résilience</li></ul><h3 id="automatisation-du-batiment" tabindex="-1">Automatisation du bâtiment <a class="header-anchor" href="#automatisation-du-batiment" aria-label="Permalink to &quot;Automatisation du bâtiment&quot;">​</a></h3><p>L&#39;objectif est que votre routine devienne automatique, quelque chose que vous faites sans y penser. Cela nécessite de la répétition :</p><ul><li>Plus de 100 lancers avec la même routine</li><li>Utilisation cohérente dans différentes situations</li><li>Exposition progressive à la pression tout en maintenant la routine</li></ul><h2 id="s-39-adapter-a-la-concurrence" tabindex="-1">S&#39;adapter à la concurrence <a class="header-anchor" href="#s-39-adapter-a-la-concurrence" aria-label="Permalink to &quot;S&amp;#39;adapter à la concurrence&quot;">​</a></h2><p>En match, votre routine pourrait nécessiter de légers ajustements :</p><ul><li><strong>Pression du temps</strong> : Préparez une version abrégée.</li><li><strong>Conditions météorologiques</strong> : Ajuster les éléments physiques en fonction des besoins</li><li><strong>Moments de forte pression</strong> : Ralentissez légèrement, n’accélérez pas.</li></ul><h2 id="la-routine-de-reinitialisation" tabindex="-1">La routine de réinitialisation <a class="header-anchor" href="#la-routine-de-reinitialisation" aria-label="Permalink to &quot;La routine de réinitialisation&quot;">​</a></h2><p>Ce que vous faites après un lancer est tout aussi important :</p><ol><li><strong>Acceptez le résultat</strong> — bon ou mauvais, c&#39;est fait.</li><li><strong>Réinitialisation physique</strong> — prenez du recul, relâchez les tensions</li><li><strong>Réinitialisation mentale</strong> — libérez votre esprit de l&#39;image du lancer</li><li><strong>Préparez-vous pour la suite</strong> — concentrez-vous sur ce qui va arriver.</li></ol><hr><p>| <em>À consulter également : <a href="/en/education/mental-strength/pre-shot-routine">Guide de routine avant le tir</a> | <a href="/en/education/mental-strength/handling-pressure">Gérer la pression</a> | <a href="/en/education/mindfulness/techniques">Techniques de pleine conscience</a></em> |</p>',54)])])}]]);export{i as __pageData,n as default};
